<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { crmProjectMap, type CrmCoverage, type CrmOverview } from '../../../src/services/personalWorkApi'
import RelationGraph from './RelationGraph.vue'
const props=defineProps<{organizationGraph?:CrmOverview['graph'];overview:CrmOverview;scope:string;initialProject:string;canWrite:boolean}>()
const emit=defineEmits<{close:[];select:[id:string,kind:string];gap:[project:string,node:string,type:string]}>()
const project=ref(props.initialProject), coverage=ref<CrmCoverage|null>(null), busy=ref(false), error=ref('')
const colors:Record<string,string>={'主管单位':'#a28cff','业主单位':'#f5c242','总包单位':'#23e0d0','设计单位':'#4596ff','厂商':'#f97316','我方':'#f5c242'}
const customers=computed(()=>props.overview.graph.nodes.filter(n=>n.kind==='person').length)
const gaps=computed(()=>coverage.value ? Object.values(coverage.value.matrix).flatMap(row=>Object.values(row)).filter(c=>c.applicable!==false&&!c.covered).length : 0)
let requestId=0
watch(project,()=>{requestId++;coverage.value=null;error.value='';busy.value=false})
async function load(){if(!project.value.trim()){error.value='请填写项目编号或名称';return}const id=++requestId;busy.value=true;error.value='';coverage.value=null;try{const result=await crmProjectMap(project.value.trim());if(id!==requestId)return;if(!result.ok)throw new Error('项目覆盖加载失败');coverage.value=result.coverage}catch(e){if(id===requestId)error.value=e instanceof Error?e.message:'加载失败，请重试'}finally{if(id===requestId)busy.value=false}}
function state(c?:{covered:boolean;applicable?:boolean;strength:number}){return !c||c.applicable===false&&!c.covered?'optional':!c.covered?'gap':c.strength>=3?'strong':'covered'}
function esc(e:KeyboardEvent){if(e.key==='Escape')emit('close')}
onMounted(()=>{window.addEventListener('keydown',esc);if(project.value.trim())load()})
onBeforeUnmount(()=>{requestId++;window.removeEventListener('keydown',esc)})
</script>
<template>
<Teleport to="body"><section class="holo-board" role="dialog" aria-modal="true" aria-labelledby="holo-title">
 <header class="holo-header"><div><p class="holo-eyebrow">客户经营 · 全息作战视图</p><h1 id="holo-title">一张图看懂：关系在哪，缺口在哪</h1><p class="holo-scope">关系范围：{{ scope }} <span> · 当前账号真实数据</span></p></div><button class="holo-close" @click="emit('close')" autofocus>退出大屏 <small>Esc</small></button></header>
 <div class="holo-content">
  <section class="holo-panel holo-network"><div class="holo-panel-head"><h2><i/>关系资产网络</h2><span>{{ customers }} 位联系人 · {{ overview.stats.relations }} 条关系</span></div>
   <div class="holo-types"><span v-for="(color,type) in colors" v-show="type!=='我方'" :key="type" :style="{'--type-color':color}"><i/>{{ type }}</span></div>
   <div class="holo-graph"><RelationGraph :organization-graph="organizationGraph" holographic :nodes="overview.graph.nodes" :edges="overview.graph.edges" :type-color="colors" :highlight-path="[]" :hidden-types="[]" :only-gaps="false" @select="(id,kind)=>emit('select',id,kind)"/><div v-if="!customers" class="holo-empty-note">建档并记录关系后，网络将在此呈现</div></div>
   <div class="holo-network-bottom"><div class="holo-legend"><span><i class="gold"/>紧密 L4+</span><span><i class="cyan"/>一般 L2–L3</span><span><i class="dashed"/>待建立 / 初识</span><span><i class="red"/>缺口 / 告警</span></div><div class="holo-alert"><span>待维系</span><strong>{{ overview.stats.warnings }}</strong><span>单点风险</span><strong>{{ overview.stats.single_point }}</strong></div></div>
  </section>
  <section class="holo-panel holo-coverage"><div class="holo-panel-head"><h2><i/>决策链热力图</h2><span>按项目全貌计算</span></div>
   <form class="holo-project" @submit.prevent="load"><label for="holo-project">项目编号 / 名称</label><div><input id="holo-project" v-model="project" placeholder="输入项目编号或名称" autocomplete="off"/><button :disabled="busy">{{ busy ? '加载中…' : '查看覆盖' }}</button></div></form>
   <p v-if="error" class="holo-error" role="alert">{{ error }}</p>
   <template v-if="coverage"><div class="holo-matrix"><table><thead><tr><th>单位 / 节点</th><th v-for="node in coverage.nodes" :key="node">{{ node }}</th></tr></thead><tbody><tr v-for="type in coverage.unit_types" :key="type"><th :style="{color:colors[type]}">{{ type }}</th><td v-for="node in coverage.nodes" :key="node"><button :class="['holo-cell',state(coverage.matrix[type][node])]" :disabled="!canWrite" :aria-label="`${type} · ${node} · ${coverage.matrix[type][node]?.covered ? '关系强度L'+coverage.matrix[type][node].strength : coverage.matrix[type][node]?.applicable===false ? '选填' : '覆盖缺口'}`" @click="emit('gap',project.trim(),node,type)">{{ coverage.matrix[type][node]?.covered ? 'L'+coverage.matrix[type][node].strength : coverage.matrix[type][node]?.applicable===false ? '—' : '!' }}</button></td></tr></tbody></table></div>
   <div class="holo-coverage-legend"><span>深蓝：选填</span><span>青色：已覆盖</span><span>金色：L3以上</span><span class="holo-error">红框：覆盖缺口 {{ gaps }}</span></div>
   <div class="holo-metrics"><div><span>应覆盖</span><strong>{{ coverage.should_cover }}</strong></div><div><span>已覆盖</span><strong>{{ coverage.covered }}</strong></div><div><span>L3以上</span><strong>{{ coverage.l3_plus }}</strong></div></div>
   <p class="holo-footnote">{{ canWrite ? '点击矩阵格子，进入决策节点登记。' : '当前为只读权限。' }}覆盖度依据实际项目节点，关系评分不替代履约证据。</p></template>
   <div v-else class="holo-no-project"><div class="holo-target">◎</div><h3>{{ busy ? '正在核查项目决策链' : '选择项目，定位覆盖缺口' }}</h3><p>加载后展示各单位在项目决策节点的关系覆盖情况。</p><p>尚未选择项目时不展示模拟统计。</p></div>
  </section>
 </div>
 <footer class="holo-footer"><span><i/>五类协同 · 关系资产到经营行动</span><span>拖动节点 · 滚轮缩放 · 点击节点查看详情</span></footer>
</section></Teleport>
</template>
<style scoped lang="scss">
