.holo-coverage{display:flex;flex-direction:column;gap:16px}.holo-project{label{font-size:11px;color:#9abbd3;display:block;margin-bottom:6px}div{display:flex;gap:8px}input{min-width:0;flex:1;background:#07172d;border:1px solid #315471;border-radius:6px;padding:9px 10px;color:white;font-size:12px}button{padding:8px 12px;border:1px solid #53dcd2;border-radius:6px;background:#155759;color:#c9fff5;font-size:12px;white-space:nowrap}}
