.holo-coverage-legend{display:flex;gap:8px 14px;flex-wrap:wrap;font-size:10px;color:#9abbcf}.holo-error{color:#ff9ca6!important;font-size:12px}.holo-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border:1px solid #ab8a3c66;background:linear-gradient(90deg,#76602522,#13314b66);border-radius:10px;padding:14px 8px;text-align:center;span{display:block;color:#c5d6e5;font-size:12px}strong{font-size:34px;color:#f5c242;font-variant-numeric:tabular-nums;text-shadow:0 0 15px #f5c24244}}.holo-footnote{font-size:10px;line-height:1.7;color:#91abc3}.holo-no-project{flex:1;display:flex;flex-direction:column;justify-content:center;text-align:center;gap:14px;h3{font-size:17px;margin:0;color:#c4e7f8}p{font-size:12px;color:#8caac3}.holo-target{font-size:100px;color:#23e0d0;text-shadow:0 0 32px #23e0d066}}
